-- Generated by tools/generate_upstream_request_adaptations.py.
-- Move the existing supplier compatibility into an explicit account capability.
-- Preserve operator choices; future URL changes do not change this capability.
UPDATE accounts
SET extra = COALESCE(extra, '{}'::jsonb) || '{"image_edits_multipart": true}'::jsonb,
    updated_at = NOW()
WHERE platform = 'openai'
  AND type = 'apikey'
  AND deleted_at IS NULL
  AND NOT (COALESCE(extra, '{}'::jsonb) ? 'image_edits_multipart')
  AND substring(lower(btrim(credentials ->> 'base_url')) FROM '^https?://([^/?#:]+)') IN (
      'api.sourcesdata.com',
      'us-direct-api.sourcesdata.com'
  );
